"""Report freshly generated wire descriptions for a fork-only UI experiment."""

import difflib
import json
import os
from pathlib import Path
import sys


report = Path(sys.argv[1])
base = report / "base"
head = report / "head"
base_files = {path.relative_to(base) for path in base.rglob("*.json")}
head_files = {path.relative_to(head) for path in head.rglob("*.json")}

for directory, files in ((base, base_files), (head, head_files)):
    if not files or Path("ids.json") not in files:
        raise RuntimeError(f"Incomplete generated descriptions in {directory}")
    for path in files:
        json.loads((directory / path).read_text())

changes = []
diffs = []
for path in sorted(base_files | head_files):
    before = (base / path).read_text() if path in base_files else ""
    after = (head / path).read_text() if path in head_files else ""
    if before == after:
        continue
    status = "Added" if path not in base_files else "Removed" if path not in head_files else "Changed"
    changes.append((status, path))
    diffs.append("".join(difflib.unified_diff(
        before.splitlines(keepends=True), after.splitlines(keepends=True),
        fromfile=f"base/{path}", tofile=f"pr/{path}",
    )))

full_diff = "\n".join(diffs)
(report / "wire.diff").write_text(full_diff)
base_sha = (report / "base-sha.txt").read_text().strip()
head_sha = (report / "head-sha.txt").read_text().strip()
summary = [
    "# Rolling upgrade compatibility — demo", "",
    "**Wire format changed — review required.**" if changes else "**No wire format changes found.**",
    "",
    f"Compared merge base `{base_sha}` with PR head `{head_sha}`.",
    "Both JSON sets were freshly generated by Maven. No JSON update was committed to this PR.",
    "",
    f"Generated descriptions: **{len(base_files)} base / {len(head_files)} PR**. Changed files: **{len(changes)}**.",
    "",
]
if changes:
    print("::warning title=Wire format changed::Review the generated JSON diff in this job summary. A difference does not determine compatibility.")
    summary += ["| Change | Description |", "| --- | --- |"]
    summary += [f"| {status} | `{path}` |" for status, path in changes]
    summary += ["", "## Generated JSON diff", "", "```diff", full_diff[:100000], "```", ""]
    if len(full_diff) > 100000:
        summary.append("Diff preview truncated. Download the artifact for the complete wire.diff.")
summary += [
    "The artifact contains the full diff, both generated JSON trees, revision IDs and build logs.",
    "",
    "This experiment detects changes. Compatibility classification and checks of hand-written transport are outside this demo.",
]
text = "\n".join(summary) + "\n"
(report / "summary.md").write_text(text)
with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as output:
    output.write(text)
